from pathlib import Path
import os

p=Path('android/app/src/main/assets/cronograma.html')
s=p.read_text(encoding='utf-8')
url=os.environ.get('SUPABASE_URL','')
key=os.environ.get('SUPABASE_PUBLISHABLE_KEY','')
if not url or not key: raise SystemExit('SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY secrets are required.')

css='''<style id="auth-security-style">#authGate{position:fixed;inset:0;z-index:10000;background:radial-gradient(circle at top,#10261b 0,#06100c 48%,#040a07 100%);display:flex;align-items:center;justify-content:center;padding:20px}#authGate .authbox{width:min(440px,100%);background:#0b1712;border:1px solid #28583f;border-radius:22px;padding:24px;box-shadow:0 22px 70px rgba(0,0,0,.55)}.auth-error{color:#ff9da3;font-size:12px;margin-top:10px;min-height:18px}.no-copy{-webkit-user-select:none;user-select:none}</style>'''
markup='''<div id="authGate" class="no-copy"><div class="authbox"><div style="font-size:34px">📚</div><h2>🔐 Acesso pessoal</h2><p class="muted">Entre com seu usuário e senha para acessar o Cronograma de Estudos APP.</p><label class="muted">Usuário</label><input id="authUsername" autocomplete="username" placeholder="Seu usuário"><label class="muted" style="display:block;margin-top:9px">Senha</label><input id="authPassword" type="password" autocomplete="current-password" placeholder="Sua senha" onkeydown="if(event.key==='Enter')window.appLogin()"><button class="btn primary" onclick="window.appLogin()" style="width:100%;margin-top:12px">Entrar</button><div id="authError" class="auth-error"></div></div></div>'''
js=r'''<script id="supabase-auth-layer">(function(){'use strict';const U='__URL__',K='__KEY__',D='login.medaprovacao.app';let sb=null,currentUser=null,loading=false;function email(u){return String(u||'').trim().toLowerCase().replace(/[^a-z0-9._-]/g,'')+'@'+D}function error(m){const e=document.getElementById('authError');if(e)e.textContent=m||''}function sdk(){return new Promise((ok,no)=>{if(window.supabase)return ok();const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';s.onload=ok;s.onerror=no;document.head.appendChild(s)})}async function cloudLoad(){if(!currentUser)return;const r=await sb.from('user_progress').select('state').eq('user_id',currentUser.id).maybeSingle();if(r.error)throw r.error;if(r.data&&r.data.state){state=r.data.state;state=state&&typeof state==='object'?state:{day:1,done:{}};state.day=Math.min(TOTAL_DAYS,Math.max(1,Number(state.day||1)));state.done=state.done&&typeof state.done==='object'?state.done:{};safeSet(KEY,JSON.stringify(state))}else{await sb.from('user_progress').upsert({user_id:currentUser.id,state},{onConflict:'user_id'})}}async function cloudSave(){if(!currentUser||loading)return;try{await sb.from('user_progress').upsert({user_id:currentUser.id,state,updated_at:new Date().toISOString()},{onConflict:'user_id'})}catch(e){console.warn('cloud save',e)}}function patchSave(){if(typeof window.save==='function')return;};async function after(user){currentUser=user;try{const p=await sb.from('profiles').select('display_name,is_active').eq('id',user.id).single();if(p.error||!p.data){await sb.auth.signOut();error('Conta não configurada.');return}if(!p.data.is_active){await sb.auth.signOut();error('Seu acesso está bloqueado.');return}await sb.rpc('touch_last_login');localStorage.setItem('med_user_id',user.id);if(typeof setUserStateKey==='function')setUserStateKey(user.id);await cloudLoad();try{setup()}catch(e){console.warn(e)}document.getElementById('authGate').style.display='none'}catch(e){console.error(e);error('Não foi possível validar seu acesso.')}}async function boot(){try{await sdk();sb=window.supabase.createClient(U,K);const oldSave=window.save;window.save=function(){try{safeSet(KEY,JSON.stringify(state));updateGlobal()}catch(e){}cloudSave()};const sess=await sb.auth.getSession();if(sess.data.session)await after(sess.data.session.user);else document.getElementById('authGate').style.display='flex';sb.auth.onAuthStateChange((_e,s)=>{if(s&&!currentUser)after(s.user)});}catch(e){console.error(e);error('Falha ao iniciar autenticação.')}}window.appLogin=async function(){if(loading)return;loading=true;error('');const u=document.getElementById('authUsername').value.trim(),p=document.getElementById('authPassword').value;if(!u||!p){error('Informe usuário e senha.');loading=false;return}const r=await sb.auth.signInWithPassword({email:email(u),password:p});loading=false;if(r.error){error('Usuário ou senha inválidos.');return}await after(r.data.user)};document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('copy',e=>e.preventDefault());document.addEventListener('cut',e=>e.preventDefault());document.addEventListener('dragstart',e=>e.preventDefault());window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['c','x','s','u','p'].includes(e.key.toLowerCase()))e.preventDefault()});boot();})();</script>'''.replace('__URL__',url.replace("'","\\'")).replace('__KEY__',key.replace("'","\\'"))

s=s.replace("const TOTAL_DAYS=200, KEY='med_aprovacao_roteiro_200_v126_state';","const TOTAL_DAYS=200; const BASE_KEY='med_aprovacao_roteiro_200_v126_state'; let KEY=BASE_KEY; function setUserStateKey(uid){KEY=uid?BASE_KEY+'_'+uid:BASE_KEY;try{state=JSON.parse(safeGet(KEY,'{\\\"day\\\":1,\\\"done\\\":{}}'));}catch(e){state={day:1,done:{}};}state=state&&typeof state==='object'?state:{day:1,done:{}};state.day=Math.min(TOTAL_DAYS,Math.max(1,Number(state.day||1)));state.done=state.done&&typeof state.done==='object'?state.done:{}}")
s=s.replace("let state; try { state=JSON.parse(safeGet(KEY,'{\"day\":1,\"done\":{}}')); } catch(e) { state={day:1,done:{}}; }\nstate=state&&typeof state==='object'?state:{day:1,done:{}};\nstate.day=Math.min(TOTAL_DAYS,Math.max(1,Number(state.day||1))); state.done=state.done&&typeof state.done==='object'?state.done:{};","let state={day:1,done:{}};")
s=s.replace('<body>','<body class="no-copy">',1)
s=s.replace('<title>Med Aprovação — Roteiro Pessoal 200 Dias — V126</title>','<title>Cronograma de Estudos APP</title>',1)
s=s.replace('</body>',css+markup+js+'\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Cloud authentication injection applied.')
